const nextReceiptNumber = `-- name: NextReceiptNumber :one
INSERT INTO receipt_counters (workspace_id, last_number) VALUES ($1, 1)
ON CONFLICT (workspace_id) DO UPDATE SET last_number = receipt_counters.last_number + 1
RETURNING last_number
`

// Takes the next number and locks the counter until the transaction ends,
// so numbers are gapless: a rolled-back issue never used one.
func (q *Queries) NextReceiptNumber(ctx context.Context, workspaceID uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextReceiptNumber, workspaceID)
	var last_number int32
	err := row.Scan(&last_number)
	return last_number, err
}

const openRequestsToRemind = `-- name: OpenRequestsToRemind :many
SELECT r.workspace_id, r.id FROM payment_requests r
WHERE r.status = 'open' AND r.due_on < $1 AND r.payer_confirmed_at IS NULL
  AND (r.last_reminded_at IS NULL OR r.last_reminded_at < $2)
  AND NOT EXISTS (SELECT 1 FROM payment_records p WHERE p.request_id = r.id AND p.superseded_at IS NULL)
ORDER BY r.due_on, r.id
LIMIT 500
`

type OpenRequestsToRemindParams struct {
	Today          time.Time
	RemindedBefore *time.Time
}

type OpenRequestsToRemindRow struct {
	WorkspaceID uuid.UUID
	ID          uuid.UUID
}

// Open requests in any team, overdue and not reminded in the last interval,
// that neither side has confirmed yet (ADR 024).
func (q *Queries) OpenRequestsToRemind(ctx context.Context, arg OpenRequestsToRemindParams) ([]OpenRequestsToRemindRow, error) {
	rows, err := q.db.Query(ctx, openRequestsToRemind, arg.Today, arg.RemindedBefore)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OpenRequestsToRemindRow
	for rows.Next() {
		var i OpenRequestsToRemindRow
		if err := rows.Scan(&i.WorkspaceID, &i.ID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

