const upsertPayeeAccount = `-- name: UpsertPayeeAccount :one
INSERT INTO payee_accounts (workspace_id, membership_id, proxy_type, proxy_value, display_name, send_automatically)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (workspace_id, membership_id) DO UPDATE
SET proxy_type = EXCLUDED.proxy_type, proxy_value = EXCLUDED.proxy_value,
    display_name = EXCLUDED.display_name, send_automatically = EXCLUDED.send_automatically,
    verified_at = CASE WHEN payee_accounts.proxy_type = EXCLUDED.proxy_type
                        AND payee_accounts.proxy_value = EXCLUDED.proxy_value
                       THEN payee_accounts.verified_at END,
    updated_at = now()
RETURNING workspace_id, membership_id, proxy_type, proxy_value, display_name, send_automatically, verified_at, created_at, updated_at
`

type UpsertPayeeAccountParams struct {
	WorkspaceID       uuid.UUID
	MembershipID      uuid.UUID
	ProxyType         ProxyType
	ProxyValue        string
	DisplayName       string
	SendAutomatically bool
}

// Changing the proxy clears verification: the new one must be scanned.
func (q *Queries) UpsertPayeeAccount(ctx context.Context, arg UpsertPayeeAccountParams) (PayeeAccount, error) {
	row := q.db.QueryRow(ctx, upsertPayeeAccount,
		arg.WorkspaceID,
		arg.MembershipID,
		arg.ProxyType,
		arg.ProxyValue,
		arg.DisplayName,
		arg.SendAutomatically,
	)
	var i PayeeAccount
	err := row.Scan(
		&i.WorkspaceID,
		&i.MembershipID,
		&i.ProxyType,
		&i.ProxyValue,
		&i.DisplayName,
		&i.SendAutomatically,
		&i.VerifiedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

